sys_ws_operation.operation_script:
(function process(request, response) {
    var body = request.body.data;

    var missing = [];
    var requiredfields = ['urgency', 'category'];
    var missingfields = [];
    var creincfun = [];
    var ermsg = '';

    requiredfields.forEach(function(field) {
        if (JSUtil.nil(body[field])) {
            missingfields.push(field);
        }
    });

    if (missingfields.length > 0) {
        var miss = _cus_error('400', "Missing required fields :" + missingfields, missingfields.join(','));
        // response.setStatus(400);
        // response.setBody({
        //     status: "failure",
        //     message: "Missing required fields :" + missingfields,
        //     errors: missingfields.join(',')
        // });
        return miss;
    }
    try {
        // var grINC = new GlideRecord('incident');
        // grINC.initialize();
        // grINC.caller_id = gs.getUserID();
        // grINC.short_description = body.short_description;
        // grINC.description = body.description;
        // grINC.category = body.category;
        // grINC.urgency = body.urgency;
        // grINC.impact = body.impact;

        // var id = grINC.insert();
        var id = createinc(body);
        var jsonid = JSON.stringify(id);
        jsonid = JSON.parse(jsonid);

        if (!jsonid[0].inc_sys_id) {
            ermsg = jsonid[0].err_inc;
            ermsg = ermsg.replace("Data Policy Exception: \n\t", "");
            var er = _getError('failure', "Invalid insert", "Invalid insert Error :" + ermsg);
            return er;
        }

        //if insert success
        response.setStatus(201);
        response.setBody({
            status: "success",
            sys_id: jsonid[0].inc_sys_id
        });

    } catch (err) {
        gs.info('REST API Error ' + err.toString());
        response.setError(new sn_ws_err.BadRequestError('Error : ' + err));
    }

    function createinc(body) {
        var grINC = new GlideRecord('incident');
        grINC.initialize();
        grINC.caller_id = gs.getUserID();
        grINC.short_description = body.short_description;
        grINC.description = body.description;
        grINC.category = body.category;
        grINC.urgency = body.urgency;
        grINC.impact = body.impact;

        var funinc = grINC.insert();
        creincfun.push({
            inc_sys_id: funinc,
            err_inc: grINC.getLastErrorMessage()
        });
        return creincfun;
    }

    function _getError(status, message, detail) {
        var Error = new sn_ws_err.ServiceError();
        Error.setStatus(status);
        Error.setMessage(message);
        Error.setDetail(detail);
        return Error;
    }

    function _cus_error(status, message, detail) {
        var myError = new sn_ws_err.ServiceError();
        myError.setStatus(status);
        myError.setMessage(message);
        myError.setDetail(detail);
        return myError;
    }


})(request, response);
